-- Migracion 045: fusion de "Bitcoin como sistema monetario" dentro de
-- "Fundamentos de Bitcoin".
--
-- Aplicada a mano el 24/09/2026 y versionada despues con el SQL exacto.
--
-- QUE CAMBIA
--
--   Fundamentos pasa de 2 modulos y 6 lecciones (14.063 caracteres) a 3
--   modulos y 9 lecciones (52.959). El tercer modulo absorbe el curso
--   monetario, que sumaba 6.272 caracteres en otras 6 lecciones.
--
--   Se eliminan las duplicaciones que detecto la auditoria de la ruta:
--   las tres funciones del dinero se explican en 1.1 y se APLICAN en 3.1,
--   sin volver a definirse; los 21 millones y el halving viven solo en
--   2.2; "que problemas resuelve" era dos lecciones y ahora es 2.3; y la
--   frase sobre confiar en reglas se enuncia una vez, en 2.1.
--
--   La 1.3 incorpora los precursores que faltaban: DigiCash, hashcash y
--   b-money, y el problema del doble gasto que ninguno resolvio.
--
--   El quiz pasa de 5 preguntas a 27, tres por leccion, todas con
--   explicacion. Antes el segundo modulo no tenia ninguna.
--
-- SLUGS
--
--   Las 6 lecciones existentes CONSERVAN su slug: los temas siguen
--   coincidiendo con las posiciones, asi que ninguna URL de Fundamentos
--   se rompe. Las 3 nuevas estrenan slug propio. Los slugs de leccion son
--   unicos por curso, no globales (hay uno repetido entre dos cursos), de
--   modo que no chocan con los del curso monetario.
--
-- LO QUE ESTA MIGRACION NO HACE
--
--   No archiva el curso monetario ni anade redirecciones. Archivar lo
--   vuelve invisible por RLS, y hasta que este desplegado el arreglo de
--   /dashboard/certificados su unico certificado emitido apareceria como
--   "Curso" a secas. Ese paso va aparte y despues.
--
-- Respaldo: C:Usersalberackups-sql%-volver-atras.sql.bak, con
-- las 19 columnas de cada leccion, slug y order_index incluidos (regla 21).

BEGIN;

-- Modulo nuevo
INSERT INTO public.modules (id, course_id, title, slug, description, order_index, total_lessons)
